    <div id="container">
        <h1>Autonóm Kereső Ágens</h1>
        <input type="text" id="queryInput" placeholder="Adja meg a kutatási témát..." style="width: 80%; padding: 8px;">
        <button onclick="startResearch()">Kutatás Indítása</button>
        <div id="output">Várakozás a parancsra...</div>
    </div>

    <script>
        const outputDiv = document.getElementById('output');
        const queryInput = document.getElementById('queryInput');
        let ws;

        function connect() {
            const proto = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
            ws = new WebSocket(`${proto}//${window.location.host}/ws`);

            ws.onopen = () => {
                outputDiv.innerHTML = '<p class="log">Kapcsolódva a szerverhez.</p>';
            };

            ws.onmessage = (event) => {
                const data = JSON.parse(event.data);
                const messageElement = document.createElement('div');

                if (data.type === 'log' || data.type === 'insight') {
                    messageElement.className = data.type;
                    messageElement.textContent = data.content;
                } else if (data.type === 'plan') {
                    let planHTML = '<h3>Kutatási Terv:</h3><ul>';
                    data.content.steps.forEach(step => {
                        planHTML += `<li>${step.task}</li>`;
                    });
                    planHTML += '</ul>';
                    messageElement.innerHTML = planHTML;
                } else if (data.type === 'final_report') {
                    messageElement.className = 'final-report';
                    messageElement.innerHTML = `<h2>Végső Jelentés</h2>${data.content}`; // Itt a markdown-t HTML-lé lehetne konvertálni
                } else if (data.type === 'image') {
                    const img = document.createElement('img');
                    img.src = data.content;
                    messageElement.appendChild(img);
                }

                outputDiv.appendChild(messageElement);
                window.scrollTo(0, document.body.scrollHeight);
            };

            ws.onclose = () => {
                outputDiv.innerHTML += '<p class="log">Kapcsolat bontva. Újracsatlakozás 5 másodperc múlva...</p>';
                setTimeout(connect, 5000);
            };
        }

        function startResearch() {
            if (ws && ws.readyState === WebSocket.OPEN) {
                const query = queryInput.value;
                outputDiv.innerHTML = ''; // Töröljük az előző outputot
                ws.send(query);
            } else {
                alert("Nincs kapcsolat a szerverrel.");
            }
        }

        connect();
    </script>
</body>
</html>
