        exa_client = Exa(api_key=os.getenv("EXA_API_KEY"))
        # Grok API az OpenAI-kompatibilis végponton keresztül
        grok_client = OpenAI(api_key=os.getenv("XAI_API_KEY"), base_url="")
        # Modal kliens
        visualize_graph_function = modal.Function.lookup("autonomous-investigator-visualizer", "create_knowledge_graph_image")
    except Exception as e:
        logging.critical(f"Kritikus hiba az API kliensek inicializálásakor: {e}")
        exit(1)

    app = FastAPI(title="Autonóm Nyomozó Ágens Backend")

    # --- Pydantic Adatmodellek a Strukturált Adatkezeléshez ---

    class Evidence(BaseModel):
        entity: str = Field(..., description="A felfedezett entitás neve (pl. személy, szervezet).")
        claim: str = Field(..., description="Az entitásra vonatkozó konkrét állítás vagy tény.")
        source: str = Field(..., description="Az információ forrása (URL).")

    class NextAction(BaseModel):
        action: str = Field(..., description="A következő teendő típusa ('search' vagy 'terminate').")
        reasoning: str = Field(..., description="Rövid indoklás, miért ez a következő logikus lépés.")
        query: str = Field(None, description="A végrehajtandó Exa keresési lekérdezés, ha az akció 'search'.")

    # --- Fő Nyomozó Osztály ---

    class AutonomousInvestigator:
        def __init__(self, websocket: WebSocket):
            self.websocket = websocket
            self.knowledge_graph = {"entities": [], "relationships": []}
            self.hypotheses: List[str] = []
            self.evidence: List[Evidence] = []
            self.investigation_log: List[str] = []
            self.grok_model = "grok-4" # Használt fő modell

        async def send_update(self, type: str, content: Any):
            """Strukturált JSON üzenetet küld a frontendnek."""
            try:
                await self.websocket.send_json({"type": type, "content": content})
            except Exception as e:
                logging.error(f"WebSocket küldési hiba: {e}")

        async def _call_grok(self, system_prompt: str, user_prompt: str, response_model: BaseModel):
            """
            Strukturált hívást indít a Grok API felé, JSON válasszal.
            Használja a 'tool use' / 'function calling' képességet a strukturált kimenethez.
            """
            await self.send_update("thinking", f"Gondolkodás ({self.grok_model})...")
            try:
                response = await asyncio.to_thread(
                    grok_client.chat.completions.create,
                    model=self.grok_model,
                    messages=[
                        {"role": "system", "content": system_prompt},
                        {"role": "user", "content": user_prompt}
                    ],
                    tools=[{"type": "function", "function": {"name": "data_extractor", "description": "Extracts data based on the provided schema.", "parameters": response_model.model_json_schema()}}],
                    tool_choice={"type": "function", "function": {"name": "data_extractor"}},
                    temperature=0.1,
                    max_retries=2,
                )
                tool_call = response.choices[0].message.tool_calls[0]
                result = json.loads(tool_call.function.arguments)
                return response_model.model_validate(result)
            except Exception as e:
                logging.error(f"Grok API hiba: {e}")
                await self.send_update("error", f"Intelligencia-mag hiba: {e}")
                return None

        async def run(self, initial_query: str):
            """A teljes, ciklikus nyomozói folyamatot futtatja."""
            self.investigation_log.append(f"Nyomozás indult: {initial_query}")

            # 1. KEZDETI HIPOTÉZISEK ALKOTÁSA
            system_prompt = "Te egy oknyomozó újságíró és elemző vagy. Feladatod, hogy a felhasználói kérés alapján több, egymást kiegészítő vagy cáfoló kezdeti hipotézist állíts fel. A hipotézisek legyenek tesztelhetők."
            user_prompt = f"A nyomozás tárgya: '{initial_query}'. Állíts fel 3-5 kezdeti hipotézist!"
            class Hypotheses(BaseModel):
                hypotheses: List[str]
            initial_hypotheses = await self._call_grok(system_prompt, user_prompt, Hypotheses)

            if not initial_hypotheses:
                await self.send_update("error", "Nem sikerült a kezdeti hipotéziseket létrehozni.")
                return

            self.hypotheses = initial_hypotheses.hypotheses
            await self.send_update("hypotheses", self.hypotheses)

            # 2. NYOMOZÓI CIKLUS
            max_iterations = 7
            for i in range(max_iterations):
                await self.send_update("log", f"Nyomozói ciklus: {i+1}/{max_iterations}")

                # 2.1. KÖVETKEZŐ LÉPÉS MEGHATÁROZÁSA
                system_prompt = "Te egy nyomozást vezető stratéga vagy. A jelenlegi hipotézisek és bizonyítékok alapján határozd meg a következő legfontosabb, megválaszolandó kérdést egy specifikus Exa keresés formájában, vagy zárd le a nyomozást, ha elegendő információ gyűlt össze."
                user_prompt = f"Jelenlegi hipotézisek:\n{self.hypotheses}\n\nJelenlegi bizonyítékok:\n{[e.model_dump_json() for e in self.evidence]}\n\nMi legyen a következő lépés?"
                next_action = await self._call_grok(system_prompt, user_prompt, NextAction)

                if not next_action or next_action.action == "terminate":
                    await self.send_update("log", f"A stratéga a nyomozás lezárása mellett döntött. Indok: {next_action.reasoning if next_action else 'Nincs több teendő.'}")
                    break

                await self.send_update("action", f"Indoklás: {next_action.reasoning}\nKeresés: '{next_action.query}'")

                # 2.2. KUTATÁS (EXA) ÉS FELDOLGOZÁS
                try:
                    search_response = await asyncio.to_thread(exa_client.search_and_contents, next_action.query, num_results=3, use_autoprompt=True)
                    new_evidence_list: List[Evidence] = []
                    for result in search_response.results:
                        if not result.text: continue

                        system_prompt = "A feladatod, hogy egy szövegből kinyerd a releváns, tényalapú állításokat és a hozzájuk tartozó entitásokat. Csak a legfontosabb, konkrét információkat add vissza."
                        user_prompt = f"Forrás URL: {result.url}\n\nSzöveg:\n{result.text[:4000]}" # Limitáljuk a szöveg hosszát a hatékonyságért
                        class EvidenceList(BaseModel):
                           findings: List[Evidence]

                        extracted_data = await self._call_grok(system_prompt, user_prompt, EvidenceList)
                        if extracted_data:
                            new_evidence_list.extend(extracted_data.findings)

                    if new_evidence_list:
                        self.evidence.extend(new_evidence_list)
                        await self.send_update("discoveries", [e.model_dump() for e in new_evidence_list])
                    else:
                        await self.send_update("log", "A keresés nem hozott új, feldolgozható bizonyítékot.")

                except Exception as e:
                    logging.error(f"Exa keresési vagy feldolgozási hiba: {e}")
                    await self.send_update("error", f"Kutatási hiba: {e}")

                # 2.3. TUDÁSGRÁF ÉS HIPOTÉZIS FRISSÍTÉSE
                system_prompt = "Te egy szintetizáló elemző vagy. A rendelkezésre álló bizonyítékok alapján frissítsd a tudásgráfot (entitások és kapcsolataik) és a hipotéziseket (finomítsd, vond össze, vagy hozz létre újakat)."
                user_prompt = f"Jelenlegi hipotézisek:\n{self.hypotheses}\n\nÖsszes bizonyíték:\n{[e.model_dump_json() for e in self.evidence]}"
                class KnowledgeUpdate(BaseModel):
                    knowledge_graph: Dict[str, List[Dict[str, Any]]] = Field(..., description="A frissített tudásgráf, ami entitásokat és kapcsolatokat tartalmaz.")
                    updated_hypotheses: List[str] = Field(..., description="A finomított, új hipotézisek listája.")

                update_result = await self._call_grok(system_prompt, user_prompt, KnowledgeUpdate)
                if update_result:
                    self.knowledge_graph = update_result.knowledge_graph
                    self.hypotheses = update_result.updated_hypotheses
                    await self.send_update("hypotheses", self.hypotheses)

                    # 2.4 VIZUALIZÁCIÓ (MODAL)
                    if self.knowledge_graph.get("entities"):
                        try:
                            await self.send_update("thinking", "Tudásgráf vizualizáció generálása...")
                            image_data_uri = await asyncio.to_thread(visualize_graph_function.remote, self.knowledge_graph)
                            if image_data_uri:
                                await self.send_update("graph_update", image_data_uri)
                        except Exception as e:
                            logging.error(f"Modal hívási hiba: {e}")
                            await self.send_update("error", "Nem sikerült a vizualizációt legenerálni.")

            # 3. VÉGSŐ JELENTÉS
            await self.send_update("log", "A nyomozás befejeződött. Végső jelentés készítése...")
            system_prompt = "Te egy Pulitzer-díjas oknyomozó újságíró vagy. Az összegyűjtött bizonyítékok és a tudásgráf alapján írj egy részletes, koherens, jól strukturált és érdekfeszítő nyomozati jelentést Markdown formátumban. Tárj fel rejtett összefüggéseket, és vond le a végső következtetést."
            user_prompt = f"A nyomozás tárgya: '{initial_query}'\n\nVégső tudásgráf:\n{json.dumps(self.knowledge_graph)}\n\nÖsszes bizonyíték:\n{[e.model_dump_json() for e in self.evidence]}\n\nÍrd meg a végső jelentést!"

            try:
                response = await asyncio.to_thread(
                    grok_client.chat.completions.create,
                    model=self.grok_model,
                    messages=[
                        {"role": "system", "content": system_prompt},
                        {"role": "user", "content": user_prompt}
                    ],
                    temperature=0.4
                )
                final_report = response.choices[0].message.content
                await self.send_update("final_report", final_report)
            except Exception as e:
                logging.error(f"Végső jelentés generálási hiba: {e}")
                await self.send_update("error", "Nem sikerült a végső jelentést elkészíteni.")

    # --- FastAPI Végpontok ---

    @app.get("/")
    async def get_root():
        """A fő HTML oldalt szolgáltatja ki."""
        try:
            with open("index.html", "r", encoding="utf-8") as f:
                return HTMLResponse(content=f.read())
        except FileNotFoundError:
            return HTMLResponse(content="<h1>Hiba: index.html nem található.</h1>", status_code=500)

    @app.websocket("/ws")
    async def websocket_endpoint(websocket: WebSocket):
        """Kezeli a WebSocket kapcsolatot és a nyomozási folyamatot."""
        await websocket.accept()
        try:
            while True:
                data = await websocket.receive_json()
                query = data.get("query")
                if query:
                    investigator = AutonomousInvestigator(websocket)
                    # A nyomozás futtatása a háttérben, hogy ne blokkolja a WebSocketet
                    asyncio.create_task(investigator.run(initial_query=query))
        except WebSocketDisconnect:
            logging.info("WebSocket kliens lecsatlakozott.")
        except Exception as e:
            logging.error(f"Váratlan hiba a WebSocketen: {e}")
            try:
                await websocket.send_json({"type": "error", "content": f"Szerverhiba történt: {e}"})
            except:
                pass # A kliens már lehet, hogy nem elérhető
